/* Upper Mahaweli and Knuckles: source-based touch exhibits, V21. */
(() => {
 'use strict';
 const U=window.StudyUI,{intro,takeaway,source,note,metrics,list,flow,figure,bindFigures,setContent,barChart,lineChart,mapWidget,esc,fmt,$,$$,openPage}=U;
 const UM=PROJECT_DATA.um,KN=PROJECT_DATA.kn;
 const umPhotos={hero:'assets/um-hero.jpg',region:'assets/um_100-4.jpg',admin:'assets/um_100-5.jpg',units:'assets/um_100-6.jpg',meeting:'assets/um_100-13.jpg',community:'assets/um_100-15.jpg',field:'assets/um_100-19.jpg',irrigation:'assets/um_100-37.jpg',canal:'assets/um_100-38.jpg',forest:'assets/um_100-50.jpg',learning:'assets/um_100-51.jpg',tankMap:'assets/um_044-28.jpg',tank0:'assets/um_044-29.jpg',tank1:'assets/um_044-30.jpg',tank2:'assets/um_044-31.jpg',tank3:'assets/um_044-32.jpg',tank4:'assets/um_044-33.jpg',tank5:'assets/um_044-34.jpg',key044:'assets/um_044-7.jpg',land044:'assets/um_044-8.jpg',soil044:'assets/um_044-23.jpg',photo044:'assets/um_044-49.jpg',key090:'assets/um_090-7.jpg',land090:'assets/um_090-8.jpg',soil090:'assets/um_090-23.jpg',photo090:'assets/um_090-42.jpg',key100:'assets/um_100-7.jpg',land100:'assets/um_100-8.jpg',soil100:'assets/um_100-23.jpg',photo100:'assets/um_100-50.jpg'};
 const knPhotos={hero:'assets/kn-hero.jpg',field:'assets/kn-field.jpg',structure:'assets/kn-structure.jpg',training:'assets/kn-training-example.jpg',extent:'assets/kn_report-1.jpg',rainFactor:'assets/kn_report-4.jpg',soilFactor:'assets/kn_report-5.jpg',coverFactor:'assets/kn_report-6.jpg',practiceFactor:'assets/kn_report-7.jpg',slope:'assets/kn_report-8.jpg',erosion:'assets/kn_report-9.jpg',export:'assets/kn_report-10.jpg',means:'assets/kn_report-11.jpg'};
 const umRef='Upper Mahaweli project brief; MWS-044, MWS-090 and MWS-100-1 management plans, 2025.';
 const knRef='Revised Inception Report, 6 April 2026. Planned technical scope; completion is not implied.';
 const knResults='Final-boundary InVEST SDR reference run; KN_Analysis.gpkg and results CSVs, October 2026. Uncalibrated model estimates on valid land cells.';
 const status=(text,planned=false)=>`<span class="project-status ${planned?'planned':''}">${text}</span>`;
 const photo=(src,alt,caption,height=380)=>`<img class="project-photo" src="${src}" alt="${esc(alt)}" style="height:${height}px"><p class="project-caption">${caption}</p>`;
 const focus=(title,text,kicker='')=>`<div class="project-focus">${kicker?`<div class="adb-kicker">${kicker}</div>`:''}<h3>${title}</h3><p>${text}</p></div>`;
 const method=(title,text)=>`<details class="project-method"><summary>${title}</summary><p>${text}</p></details>`;
 const colors=['#29765e','#0696a5','#c69238','#558c81','#9fbe8b','#7f7665'];
 function tabs(host,labels,fn,initial=0){let selected=initial;const el=$(host);function draw(){el.classList.add('project-tabs');el.innerHTML=labels.map((x,i)=>`<button type="button" data-pick="${i}" aria-pressed="${i===selected}">${x}</button>`).join('');el.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{selected=+b.dataset.pick;draw();});fn(selected);}draw();}
 function cases(host,fn,initial=0){const el=$(host);let selected=initial;function draw(){el.className='project-cases';el.innerHTML=UM.map((p,i)=>`<button type="button" data-case="${i}" aria-pressed="${i===selected}"><b>MWS-${p.id}</b><small>${p.place}</small></button>`).join('');el.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{selected=+b.dataset.case;draw();});fn(UM[selected]);}draw();}
 function decisions(host,items,initial=0){const el=$(host);el.innerHTML='<div class="project-milestones"></div><div class="decision-content"></div>';const nav=el.firstChild,detail=el.lastChild;function draw(i){nav.innerHTML=items.map((r,j)=>`<button type="button" data-decision="${j}" aria-pressed="${i===j}"><b>${String(j+1).padStart(2,'0')}</b><span>${r[0]}</span><em>↗</em></button>`).join('');detail.innerHTML=focus(items[i][1],items[i][2],items[i][3]||'Explore the approach');nav.querySelectorAll('button').forEach(b=>b.onclick=()=>draw(+b.dataset.decision));}draw(initial);}
 function pairBands(title,rows){return `<div class="project-compare"><h3>${title}</h3>${rows.map(([label,value])=>`<div class="project-band"><div><span>${label}</span><b>${fmt(value,1)}%</b></div><span class="band-track"><i style="width:${value}%"></i></span></div>`).join('')}</div>`;}
 function jumpButtons(items){return '<div class="project-tabs">'+items.map(([label,c,t])=>`<button type="button" data-jump="${c},${t}">${label} ↗</button>`).join('')+'</div>';}
 function bindJumps(){$$('[data-jump]').forEach(b=>b.onclick=()=>openPage(...b.dataset.jump.split(',').map(Number)));}

 // UPPER MAHAWELI — integrated planning, not the ADB hydrological assignment.
 function umPurpose(){setContent(intro('Plan locally. Protect a connected watershed.','Upper Mahaweli links the health of upland landscapes with water, food, energy and livelihoods far downstream.','Integrated watershed management')+metrics([['3,111 km²','watershed area'],['36','Divisional Secretariats'],['224','mini-watershed plans']])+photo(umPhotos.hero,'A reservoir and upland landscape','Original project photograph · Upper Mahaweli')+takeaway('IWMI’s assignment prepared integrated mini-watershed management plans under the Integrated Watershed and Water Resources Management Project (IWWRMP).')+list([['A practical planning scale','Combine local needs and technical evidence in a mini-watershed, where land use and water pathways can be considered together.'],['A shared responsibility','Proposals bring communities, local administration and sector agencies into one planning framework. Implementation follows through the responsible institutions.']])+source(umRef+' These are planning outputs, not a count of completed restoration interventions.'));}
 function umGeography(){setContent(intro('One watershed, many local planning areas.','Explore the project’s original maps. Touch a map to enlarge, then pinch or use the zoom controls.')+'<div id="um-region-tabs"></div><div id="um-region-map"></div>'+takeaway('The planning assignment covers 36 Divisional Secretariats in Kandy, Nuwara Eliya and Badulla. Mini-watershed boundaries help connect work across village and sector boundaries.')+source('MWS-100-1 plan, Figures 1.1–1.3. Maps are reproduced as report figures; they are not parcel or engineering boundaries.'));
  const ms=[['Watershed','region','Upper Mahaweli watershed'],['Administration','admin','Administrative divisions within the Upper Mahaweli watershed'],['Mini-watersheds','units','Distribution of mini-watersheds in the Upper Mahaweli project']];tabs('#um-region-tabs',ms.map(x=>x[0]),i=>{$('#um-region-map').innerHTML=figure(ms[i][1],ms[i][2],760);bindFigures();});}
 function umPressures(){setContent(intro('Land, water and livelihoods are connected.','The plans address pressures together because a change on a slope can affect farms, streams, reservoirs and communities.')+'<div id="um-pressures"></div>'+source(umRef+' Project context and objectives, Chapters 1–2.'));
  decisions('#um-pressures',[['Productive soils','Keep soil on the land.','Erosion and declining soil quality reduce agricultural productivity and can increase sediment delivery to waterways. Soil conservation belongs alongside farm management.'],['Reliable water','Protect sources and water pathways.','Seasonal shortages, damaged local infrastructure, pollution pressures and encroached stream reservations require location-specific management.'],['Healthy vegetation','Maintain protective vegetation.','Forests, streamside vegetation and well-managed agricultural cover help stabilise slopes and sustain ecosystem functions.'],['Secure livelihoods','Make conservation workable for households.','Production costs, skills, market access and income opportunities influence whether land-management measures can be adopted and maintained.']]);}
 function umApproach(){setContent(intro('Evidence-informed watershed planning.','Geospatial assessment, field investigations and stakeholder engagement connect the landscape with local priorities.','How the plans were developed')+'<div id="um-process"></div>'+photo(umPhotos.community,'Community meeting at Makkanigama','Community engagement recorded in the MWS-100-1 plan',330)+source('Mini-watershed plans, Chapters 1, 3 and 4.'));
  decisions('#um-process',[['Geospatial assessment','Understand the landscape.','Map terrain, drainage, land use, soils and erosion hazards. The plans describe mini-watershed delineation using a 5 m DEM derived from MASL contours and spot heights.'],['Field investigations','Ground the proposals in local conditions.','Joint visits by field managers, community representatives and technical staff examine problems and candidate sites. Photographs, locations and observations support the proposals.'],['Stakeholder engagement','Bring community priorities into the plan.','Grassroots planning committees identify needs. Multi-disciplinary mini-watershed committees and sector specialists review proposals and help define responsibilities.'],['Integrated planning','Specify what, where and who.','Combine sector proposals with indicative costs, contributions, priorities and timeframes. The resulting plan is a basis for coordinated implementation and follow-up.']]);}
 function umParticipation(){setContent(intro('Local knowledge is part of the evidence.','A bottom-up process links community priorities with specialist assessment and administrative support.')+`<div class="project-pair"><div><img src="${umPhotos.community}" alt="Makkanigama community meeting"><p>Community discussions</p></div><div><img src="${umPhotos.meeting}" alt="Kandy District Secretariat meeting"><p>District-level coordination</p></div></div>`+flow([['Grassroots planning committees','Community representatives and field officers identify local problems, propose activities and discuss the resources needed.'],['Mini-watershed planning committees','Multi-disciplinary representatives bring local priorities together and assess their relevance across the planning unit.'],['Technical agencies and specialists','Relevant agencies guide sector proposals, while the consultancy team evaluates technical suitability and integration.']])+takeaway('Participation is not a single consultation at the end. It helps shape the proposals, their priorities and the arrangements needed to sustain them.')+source('MWS-100-1 plan, Chapter 3, Figures 3.1–3.7.'));}
 function umPlanContents(){setContent(intro('A plan that connects diagnosis with delivery.','Each mini-watershed plan records the local context, the management proposals and the arrangements needed to take them forward.')+'<div id="um-plan-contents"></div>'+source('Mini-watershed management plans, Chapters 2–5 and proposal tables. Cost estimates and schedules are plan-specific; they are not expenditure or implementation records.'));
  decisions('#um-plan-contents',[['Landscape profile','Know the planning unit.','Boundary and administrative maps; land use, terrain, soils, climate and demographic context provide the starting point.'],['Priority issues','Identify the local constraints.','Erosion hazards, water-source problems, infrastructure condition, vegetation pressures and livelihood constraints are documented.'],['Management proposals','Describe the proposed response.','Activities are identified by location and sector, with quantities, indicative costs, contributions and timeframes where provided.'],['Institutions and skills','Make follow-through possible.','Responsibilities, organisational strengthening, capacity development and practical coordination are included so the plan can be carried into action.']]);}
 function umFramework(){setContent(intro('Six priorities. One integrated plan.','Touch land, water or people to see how the management themes fit together.')+'<div class="project-wheel" id="um-wheel"></div><div class="project-wheel-caption">Touch a coloured sector</div><div id="um-wheel-detail"></div>'+source('Upper Mahaweli approved project brief; six priority themes across the mini-watershed plans.'));
  const rows=[['LAND','#246b55','Protect the productive landscape.','Soil and water conservation','Protect cultivated soils through locally suitable conservation and runoff management.','Forest and vegetation management','Conserve and improve protective vegetation in the wider landscape.'],['WATER','#009aa6','Care for sources and waterways.','Stream and riparian protection','Protect stream reservations, vegetation and drainage corridors.','Water resource improvement','Address identified needs in springs, wells, tanks, irrigation and domestic-water systems.'],['PEOPLE','#bd8f32','Support livelihoods that sustain conservation.','Agricultural land improvement','Improve land management and production practices in ways suited to the location.','Livelihood strengthening','Develop skills, production support and market connections alongside watershed management.']];
  function pt(a,r){a=a*Math.PI/180;return [300+r*Math.sin(a),300-r*Math.cos(a)];}function arc(a,b){const A=pt(a,264),B=pt(b,264),C=pt(b,133),D=pt(a,133);return `M${A} A264 264 0 0 1 ${B} L${C} A133 133 0 0 0 ${D} Z`;}
  $('#um-wheel').innerHTML=`<svg viewBox="0 0 600 600" aria-label="Land, water and people: six management priorities">${rows.map((r,i)=>{const q=pt(i*120+60,202);return `<g role="button" tabindex="0" data-sector="${i}" aria-label="${r[0]}"><path fill="${r[1]}" d="${arc(i*120+3,(i+1)*120-3)}"/><text x="${q[0]}" y="${q[1]+10}" text-anchor="middle">${r[0]}</text></g>`;}).join('')}<text class="wheel-centre" x="300" y="295" text-anchor="middle">224</text><text class="wheel-small" x="300" y="330" text-anchor="middle">local plans</text></svg>`;
  function choose(i){const r=rows[i];$('#um-wheel-detail').innerHTML=focus(r[2],`<b>${r[3]}</b><br>${r[4]}<br><br><b>${r[5]}</b><br>${r[6]}`);$$('[data-sector]').forEach((g,j)=>{g.setAttribute('aria-pressed',i===j);g.querySelector('path').setAttribute('opacity',i===j?'1':'.68');});}
  $$('[data-sector]').forEach(g=>{g.onclick=()=>choose(+g.dataset.sector);g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(+g.dataset.sector);}};});choose(0);}
 function umLand(){setContent(intro('Conserve soil while sustaining production.','Land-management proposals combine protective cover, suitable conservation practices and the needs of existing farms.')+'<div id="um-land-tabs"></div><div id="um-land-detail"></div>'+source('MWS-100-1 and MWS-090 plans, soil/water conservation, forest management and agriculture sections. Proposed measures require site-specific selection.'));
  const r=[['Soils','Keep runoff from carrying soil downslope.','The plans include combinations of contour practices, stone terracing, lock-and-spill drains and vegetative measures, where appropriate to slope and land use.','field'],['Vegetation','Manage the whole cover mosaic.','Natural vegetation, forest patches, plantations, home gardens and streamside cover have different management needs. Proposals address protection, enrichment and maintenance.','forest'],['Farming','Link conservation with farm viability.','Soil management, better crop practices and support for production are considered alongside skills and market opportunities. A conservation proposal must be workable for the people managing the land.','photo090']];tabs('#um-land-tabs',r.map(x=>x[0]),i=>{$('#um-land-detail').innerHTML=photo(umPhotos[r[i][3]],r[i][1],'Field photograph from the mini-watershed plans',460)+focus(r[i][1],r[i][2]);});}
 function umWater(){setContent(intro('Start with a specific water problem.','The plans connect field observations to proposed improvements for sources, local supply and irrigation.')+'<div id="um-water-tabs"></div><div id="um-water-detail"></div>'+takeaway('These examples are proposals recorded in the plans. The photographs show existing conditions, not completed improvements.')+source('MWS-100-1 plan, water-resource management and minor-irrigation tables; MWS-044 plan, tank inventory.'));
  const r=[['Sources','Protect springs and local supply.','Investigations identify protection, storage, treatment or repair needs at named water sources and community systems.','field'],['Irrigation','Improve the performance of existing systems.','At Kolagahamula in Galpihilla, the plan records damaged sections of canal and proposes repairs, lining and associated drainage works.','irrigation'],['Tanks','Assess storage and maintenance needs.','The MWS-044 plan inventories six tank/anicut sites. Proposed responses differ between sites, including sluice repairs, bund work and desilting.','tank3']];tabs('#um-water-tabs',r.map(x=>x[0]),i=>{$('#um-water-detail').innerHTML=photo(umPhotos[r[i][3]],r[i][1],'Original field photograph · mini-watershed plan',450)+focus(r[i][1],r[i][2]);});}
 function umPeople(){setContent(intro('Conservation needs viable livelihoods.','The plans recognise that training, farm performance, access to inputs and market opportunities affect long-term uptake.')+photo(umPhotos.learning,'Discussion with agrarian officers','Discussion with agrarian officers recorded in the Kundasale plan',370)+list([['Listen to practical constraints','Makkanigama and Galpihilla communities identified input costs, quality seeds, animal damage, skills, equipment and market access among their concerns.'],['Strengthen opportunities','Proposals cover producer groups, value chains, processing and value addition, market links and suitable livelihood activities.'],['Build skills and institutions','Training and organisational support help communities and agencies manage activities beyond preparation of the plan.']])+takeaway('The intended outcome is stronger livelihoods alongside healthier land and water. This exhibit does not claim that household incomes have already increased.')+source('MWS-100-1 plan, livelihood challenges and expectations table; agriculture, marketing and capacity-development sections.'));}
 function umCases(){setContent(intro('Three places, three different landscapes.','Select a mini-watershed to explore its original location and land-use maps. These are examples from the 224-plan programme.','Source-plan explorer')+'<div id="um-cases"></div><div id="um-case-maps"></div><div id="um-case-detail"></div>'+source('Source plans: MWS-044 (Uva Paranagama), MWS-090 (Medadumbara) and MWS-100-1 (Kundasale); Figures 2.1–2.2 and Table 2.2.'));
  let layer=0;const render=p=>{const key=p.id==='100-1'?'100':p.id;$('#um-case-detail').innerHTML=metrics([[fmt(p.area,2)+' km²','area from land-use table'],[fmt(Math.max(...p.landuse.map(r=>r.share)),1)+'%','largest mapped land-use share']])+figure((layer?'land':'key')+key,`MWS-${p.id} · ${layer?'land use':'location map'}`,650)+note(p.id==='090'?'MWS-090’s executive summary contains a conflicting area. This view uses the land-use table’s mapped extent (1,892.53 ha); see Sources.':'Areas refer to the mapped mini-watershed, not the full administrative division.');bindFigures();};let current=UM[0];cases('#um-cases',p=>{current=p;render(p);});tabs('#um-case-maps',['Location','Land use'],i=>{layer=i;render(current);});}
 function umLanduse(){setContent(intro('Different land uses call for different responses.','Compare the composition of the three source plans. Touch any bar for its exact mapped share.')+'<div id="um-lulc-cases"></div><div id="um-lulc-chart"></div><div id="um-lulc-insight"></div>'+source('Each plan, Table 2.2. Land-use maps credited to LUPPD, 2024. Shares are rounded in the reports and describe these three examples only.'));
  cases('#um-lulc-cases',p=>{const sorted=[...p.landuse].sort((a,b)=>b.share-a.share);barChart('#um-lulc-chart',sorted.map((r,i)=>({label:r.name,value:r.share,color:colors[i%colors.length]})),{unit:'% of mapped area',title:'Land use · MWS-'+p.id,max:100});$('#um-lulc-insight').innerHTML=takeaway(`<b>${sorted[0].name}</b> covers ${fmt(sorted[0].share)}% of MWS-${p.id}. Planning needs to reflect this mix of land uses and local management conditions.`);});}
 function umErosion(){setContent(intro('Use the hazard assessment to focus attention.','The plans classify potential soil loss into five categories. Compare the share of land in each class.','Model-based planning evidence')+'<div id="um-soil-cases"></div><div id="um-soil-chart"></div><div id="um-soil-insight"></div>'+source('Source plans, Table 5.1 and Figure 5.1. These are mapped erosion-hazard classes, not measurements of annual sediment entering a reservoir.'));
  cases('#um-soil-cases',p=>{barChart('#um-soil-chart',p.erosion.map((r,i)=>({label:r.name,value:r.share,color:['#c6d9bb','#93bd9b','#dfbd69','#d68c42','#ad5a35'][i]})),{unit:'% of mapped area',title:'Erosion-hazard class · MWS-'+p.id,max:50});$('#um-soil-insight').innerHTML=takeaway(`<b>${fmt(p.highShare,1)}%</b> is classified as high or very high potential soil loss in this plan. The mapped pattern helps guide local investigation and suitable conservation proposals.`)+figure('soil'+(p.id==='100-1'?'100':p.id),'Erosion-hazard map · MWS-'+p.id,450);bindFigures();});}
 function umRain(){setContent(intro('Plan for the seasonal rhythm of rainfall.','Compare the monthly rainfall profiles reported in the three mini-watershed plans.','Reported monthly profiles')+'<div id="um-rain-tabs"></div><div id="um-rain-chart"></div>'+takeaway('All three profiles show a wetter October–December period and lower rainfall around the middle of the year. This helps frame soil protection, water storage and farm planning discussions.')+method('How to read this chart','The chart reproduces the twelve monthly values in each source plan. It does not present a rainfall trend or a forecast. The annual row is omitted because some entries conflict with the monthly values, especially MWS-090. The exhibit does not assume a common observation period where the tables do not specify one.')+source('Source plans, monthly rainfall tables in Chapter 2. Annual totals are not plotted.'));
  tabs('#um-rain-tabs',['Compare all','MWS-044','MWS-090','MWS-100-1'],i=>lineChart('#um-rain-chart',(i?[UM[i-1]]:UM).map(p=>({name:'MWS-'+p.id,values:p.rain,color:colors[UM.indexOf(p)]})),'mm','Monthly rainfall profiles'));}
 function umTanks(){setContent(intro('From an inventory to a site-specific proposal.','Explore the six sites listed in the MWS-044 tank and anicut inventory.','Uva Paranagama · example plan')+'<label class="adb-field">Select a site<select id="um-tank-select"></select></label><div id="um-tank-detail"></div>'+figure('tankMap','Location map of tank sites · MWS-044',430)+source('MWS-044 plan, tank inventory and Figures 5.4–5.10. Names follow the plan; the final inventory entry is labelled an anicut/canal. Proposals are not completed works.'));
  const rows=[['Gibiliyagaha Madiththa Wewa','Ambagasdowa','Desilting and a security fence.'],['Mahathenna Wewa','Daragala','Desilting and sluice repairs.'],['Katugalla Asvedduma Wewa','Daragala','Desilting and sluice repairs.'],['Dibibedda Uda Wewa','Kotawera Udagama','Desilting and bund rehabilitation.'],['Dibibedda Pahala Wewa','Kotawera Udagama','Repair of the gravel access road on the bund.'],['Thithamaluwa anicut and canal','Kotawera Udagama','Rehabilitation, as described in the inventory.']];$('#um-tank-select').innerHTML=rows.map((r,i)=>`<option value="${i}">${r[0]}</option>`).join('');function draw(){let i=+$('#um-tank-select').value,r=rows[i];$('#um-tank-detail').innerHTML=photo(umPhotos['tank'+i],r[0],'Existing conditions recorded in the plan',430)+focus(r[0],r[2],r[1]+' · proposed response');}$('#um-tank-select').onchange=draw;draw();}
 function umImplementation(){setContent(intro('A shared route from plan to action.','The plans give institutions and communities a basis for coordinating investment, responsibilities and maintenance.','Implementation framework')+flow([['Agree the local priorities','Use the mini-watershed diagnosis and community proposals to identify suitable activities and sequence the work.'],['Confirm feasibility and resources','Review site conditions, technical requirements, indicative costs, contributions and the availability of funding.'],['Assign delivery and maintenance','Bring the relevant line agencies, local administration and community groups together around clear responsibilities.'],['Review progress and adjust','Track implementation and the condition of land, water systems and livelihoods; revise activities in response to experience.']])+takeaway('The 224 plans provide a planning foundation. Delivery and outcomes depend on implementation, sustained institutional support and local participation.')+source('Mini-watershed plans, proposal, responsibility, cost and timeframe tables. This is an exhibit synthesis of the implementation logic.'));}
 function umLearning(){setContent(intro('Keep knowledge and responsibility local.','Capacity development is part of sustaining watershed management beyond the preparation of a document.')+photo(umPhotos.learning,'Local technical discussion','Planning discussion in the Kundasale mini-watershed report',400)+'<div id="um-skills"></div>'+source('Mini-watershed plans, capacity-building proposals, institutional arrangements and livelihood development sections.'));
  decisions('#um-skills',[['Practical land and water skills','Support everyday management.','Build the skills needed to maintain conservation practices, manage local water resources and improve agricultural production.'],['Organisation and markets','Strengthen collective action.','Producer groups, community organisations and links to technical services can support shared management and more viable livelihood activities.'],['Institutional continuity','Keep the plan in use.','Clear responsibilities, access to information and continued technical support help keep activities coordinated as conditions change.']]);}
 function umSummary(){setContent(intro('Healthy land. Secure water. Stronger livelihoods.','Upper Mahaweli’s contribution is a connected planning framework that turns local evidence into coordinated proposals.')+metrics([['224','mini-watershed plans'],['6','priority themes'],['3','districts in the assignment']])+list([['What the project provides','Spatial diagnosis, field-informed proposals, community engagement, indicative resources and institutional arrangements.'],['What the examples reveal','Neighbouring planning units can have very different land-use mixes, hazard patterns and water-system needs.'],['What comes next','Prioritised implementation, appropriate technical checks, resourcing, local ownership and sustained follow-up.']])+jumpButtons([['Explore the six themes',2,0],['Compare source plans',3,0],['Planning approach',1,0]])+source(umRef));bindJumps();}
 function umSources(){return intro('Evidence behind Upper Mahaweli.','The exhibit combines programme-level context with three detailed source-plan examples.')+list([['Programme context','Upper Mahaweli Watershed Management in Sri Lanka_new.docx: 3,111 km², 36 Divisional Secretariats, 224 mini-watershed plans and six priority themes.'],['MWS-044 · Uva Paranagama','Mini-Watershed Management Plan-MWS-044.docx, dated September 2025. Land use, rainfall, erosion-hazard classes, tank inventory and original field photographs.'],['MWS-090 · Medadumbara','Mini-Watershed Management Plan-MWS-090_revised.docx. Land-use and erosion tables, monthly rainfall, location and thematic maps.'],['MWS-100-1 · Kundasale','Mini-Watershed Management Plan-MWS-100-1.docx, July 2025. Planning methods, participation, regional maps, local water systems, livelihood constraints and capacity-development proposals.']])+method('Scope of the examples','Only three source plans are explored in detail here. Their percentages and photographs do not represent a statistical sample of all 224 plans. Regional maps are original report figures with zoom; the exhibit does not invent an interactive 224-polygon dataset.')+method('Conflicting area and rainfall entries','MWS-090’s executive summary reports 3.97 km² while its land-use table totals 1,892.53 ha. The case explorer explicitly uses the mapped land-use-table extent (18.93 km²). Annual rainfall rows conflict with monthly entries in some plans. Only the twelve reported monthly values are plotted, without assuming identical reference periods. Rounded percentages can differ slightly from 100%.')+method('Plans, observations and outcomes','Maps and hazard classes are planning evidence. Field photographs document existing conditions. Costed activities and schedules are proposals, not records of expenditure, completed construction or measured improvement. The diagram and connecting narrative are a synthesis of the plans.')+source('Prepared for the IWMI Open Day touchscreen. Sources, extracted tables, image provenance and preparation script are retained in this version’s research_projects folder.');}
 const umChapters=[
  {title:'The watershed & its purpose',desc:'Why a connected landscape needs integrated local plans.',topics:['Purpose','Project maps','Connected pressures'],fn:[umPurpose,umGeography,umPressures]},
  {title:'How the plans were developed',desc:'Spatial evidence, local investigations and participation.',topics:['Planning approach','Participation','Inside a plan'],fn:[umApproach,umParticipation,umPlanContents]},
  {title:'Land, water & people',desc:'Explore the six management themes together.',topics:['Six priorities','Land','Water','People'],fn:[umFramework,umLand,umWater,umPeople]},
  {title:'Explore local evidence',desc:'Maps and comparisons from three source plans.',topics:['Map explorer','Land use','Erosion hazards','Rainfall'],fn:[umCases,umLanduse,umErosion,umRain]},
  {title:'From proposals to delivery',desc:'Site-specific needs and shared responsibilities.',topics:['Tank inventory','Implementation','Skills & institutions'],fn:[umTanks,umImplementation,umLearning]},
  {title:'The planning legacy',desc:'What the plans provide and how they can be used.',topics:['Key messages'],fn:[umSummary]}
 ];
 window.registerStudyProject('mahaweli',{data:{},photos:umPhotos,chapters:umChapters,title:'Upper Mahaweli',plainTitle:'Upper Mahaweli watershed management',subtitle:'Integrated planning for land, water and people.',kicker:'IWMI · Integrated watershed planning',heroAlt:'Upper Mahaweli reservoir and mountain landscape',overviewTitle:'A local plan. A connected landscape.',overviewText:'Explore how 224 mini-watershed plans connect scientific evidence, community priorities and practical management.',metrics:[['224','mini-watershed plans'],['36','Divisional Secretariats'],['6','management themes']],sources:umSources});

 // KNUCKLES — hydrological evidence, analytical support and capacity development.
 function knPurpose(){setContent(intro('Water science for climate resilience.','The Knuckles hydrological study connects upland water processes with downstream communities, irrigation and water infrastructure.','IWMI’s contribution to the GCF Knuckles Project')+photo(knPhotos.hero,'Knuckles Mountain Range','Landscape photograph from the Inception Report',420)+list([['Understand water and climate','Assess water resources, demand, erosion, connectivity and future flood and drought risks.'],['Inform watershed planning','Provide maps, model results and technical guidance to the teams responsible for design and implementation.'],['Strengthen skills and learning','Support agencies with practical tools, training, guidelines and monitoring approaches.']])+takeaway('IWMI provides technical analysis and planning support. Detailed engineering and implementation of field interventions are responsibilities of the designated partner teams.')+source('Revised Inception Report, Tasks 1–6, especially Sections 5.3–5.5.'));}
 function knBoundary(){setContent(intro('Start with a common hydrological framework.','The adopted erosion-assessment framework contains 35 sub-watersheds across four river basins.')+metrics([['35','sub-watersheds'],['12 / 23','upstream / downstream'],['4','river basins']])+figure('extent','Knuckles study framework · sub-watersheds and water bodies',660)+takeaway('A consistent spatial framework lets different analyses be compared and shared. The analytical boundary includes both upstream and downstream planning units.')+method('Boundary and area','The supplied final model boundary measures approximately 7,321.5 km² from geometry. Some report tables use a delivered area attribute of 7,322.37 km². This exhibit uses the geometry-based area for calculations. Programme footprint figures in the original brief describe a different context and are not mixed with this boundary.')+source('September 2026 delineation report; final-boundary geodatabase and October erosion report. The figure is a report map, with touch zoom.'));}
 function knFramework(){setContent(intro('One study framework, several connected questions.','Explore the six workstreams in IWMI’s assignment. Each contributes a different part of the evidence needed for planning.')+'<div id="kn-workstreams"></div>'+source(knRef));
  decisions('#kn-workstreams',[['Hydrology & climate','How much water is available, and when?','Assess baseline water resources and uses, model the hydrological system and examine changing climate risks.'],['Connectivity & vulnerability','Which places and systems are exposed?','Connect upstream and downstream processes, water availability, infrastructure conditions and vulnerabilities.'],['Technical integration','How can evidence support other teams?','Share compatible maps, hydrological results and strategic guidance through the Mahaweli Consultancy Bureau.'],['Watershed recommendations','Which responses fit the evidence?','Use spatial diagnosis and model scenarios to inform conservation priorities and the design work of partner teams.'],['Capacity development','Who can use the tools over time?','Strengthen agencies’ ability to manage datasets, operate models, interpret scenarios and apply the results.'],['Monitoring & learning','How will the project learn?','Develop indicators, responsibilities and reporting approaches that support review and adaptive management.']]);}
 function knMap(){setContent(intro('Explore the 35 sub-watersheds.','Select a place or change the map measure. Compare local contribution with the intensity of modelled erosion.','Available model evidence · October 2026')+'<div id="kn-map" class="project-data-view"></div>'+takeaway('A high mean rate identifies intensive erosion or delivery per hectare. A high contribution identifies a large share of the modelled total. Both matter for prioritisation.')+method('Interpretation and coverage','These are local sheet-and-rill erosion and sediment-delivery estimates, not cumulative loads at an outlet or deposition in a tank. Means use valid model land cells only; stream cells and missing-data cells are excluded. Values are planning references and have not been calibrated against measured sediment loads.')+source(knResults));
  mapWidget('#kn-map','watersheds',{metric:'share',label:'Share of modelled sediment export',unit:'%',initial:'60-03',selectionLabel:'sub-watershed',metricOptions:[{key:'share',label:'Contribution to modelled sediment export',unit:'%'},{key:'export',label:'Mean sediment delivery to streams',unit:'t/ha/year'},{key:'soil',label:'Mean gross soil erosion',unit:'t/ha/year'},{key:'area',label:'Geographical area',unit:'km²'}],detail:(f,m,l,u)=>`<div><h3>${esc(f.name)}</h3><p>${f.id} · ${esc(f.basin)} · ${f.position==='Up Stream'?'Upstream':'Downstream'}</p><small>${fmt(f.area,1)} km² geographical area<br>${fmt(f.valid,1)} km² with valid export data</small></div><div><strong>${fmt(f[m],2)}${u==='%'?'%':''}</strong><small>${esc(l)}${u!=='%'?' ('+u+')':''}</small></div>`});}
 function knContribution(){setContent(intro('A concentrated upstream contribution.','A small part of the mapped area accounts for a large share of modelled sediment delivery to streams.','Relative model contributions')+'<div id="kn-contribution-tabs"></div><div id="kn-contribution-insight"></div><div id="kn-contribution-chart"></div>'+method('What the shares mean','Shares use the final-boundary reference model. They describe sediment generated locally and delivered to streams from each unit. They do not show sediment trapped in downstream reservoirs, nor the combined load passing a sub-watershed outlet.')+source(knResults));
  tabs('#kn-contribution-tabs',['Upstream / downstream','Leading contributions','Four river basins'],i=>{
   if(i===0){$('#kn-contribution-insight').innerHTML=pairBands('Upstream units: area and contribution',[['Share of geographical area',KN.upstreamAreaShare],['Share of modelled sediment export',KN.upstreamShare]])+takeaway('The 12 upstream units contribute about '+fmt(KN.upstreamShare,1)+'% of modelled sediment export, while covering '+fmt(KN.upstreamAreaShare,1)+'% of the analytical area.');barChart('#kn-contribution-chart',[{label:'Upstream',value:KN.upstreamShare,color:'#008e9d'},{label:'Downstream',value:100-KN.upstreamShare,color:'#b7cfc1'}],{title:'Share of modelled sediment export',unit:'%',max:100});}
   if(i===1){const top=[...KN.features].sort((a,b)=>b.share-a.share).slice(0,8);$('#kn-contribution-insight').innerHTML=takeaway('<b>Hulu Ganga, Sudu Ganga, Hasalaka Oya and Middle Mahaweli</b> together contribute '+fmt(KN.top4share,1)+'% of modelled export from '+fmt(KN.top4areaShare,1)+'% of the geographical area.');barChart('#kn-contribution-chart',top.map((f,j)=>({label:f.name,short:f.name.length>23?f.id+' · '+f.name.slice(0,16)+'…':f.name,value:f.share,color:j<4?'#008e9d':'#7facad'})),{title:'Leading local contributions',unit:'% of modelled total',max:30});}
   if(i===2){$('#kn-contribution-insight').innerHTML=takeaway('The Mahaweli portion dominates modelled sediment delivery in this analytical framework. The other three basins remain part of the connected planning context.');barChart('#kn-contribution-chart',KN.basinRows.filter(r=>r.Metric==='Export').map(r=>({label:r.Basin_Name,value:r.Total_t_yr/KN.total*100})).sort((a,b)=>b.value-a.value),{title:'Modelled export by river basin',unit:'% of modelled total',max:100,color:'#008e9d'});}
  });}
 function knLanduse(){setContent(intro('Read land cover and model assumptions together.','Compare mapped area with modelled sediment contribution. A small exposed area can have a disproportionate influence.')+'<div id="kn-cover-tabs"></div><div id="kn-cover-chart"></div>'+takeaway('Mapped landslide surfaces occupy about 0.23% of the area but contribute about 16.3% of modelled export. The model represents exposed surfaces after landslides—not the mass of material moved by a landslide.')+method('Why forest contribution needs careful interpretation','The broad forest category covers a large area. In the reference run, open forest was assigned dense-forest cover/practice values. Land cover, slope, rainfall and modelling assumptions all affect results. A high total contribution from a broad class does not establish that healthy forest causes erosion or should be removed.')+source('Final-boundary Landuse_contributions.csv; October revised erosion report, Table 16 and limitations.'));
  const rows=KN.landuse.filter(r=>['Agricultural Land','Forest Lands','Landslide Area','Bare Land','Built up Land'].includes(r.Landuse_class));tabs('#kn-cover-tabs',['Area share','Export share','Mean export'],i=>{const field=['Mapped_area_percent','Export_Total_percent','Export_Mean_t_ha_yr'][i];barChart('#kn-cover-chart',rows.map((r,j)=>({label:r.Landuse_class,value:r[field],color:colors[j]})),{title:['Share of mapped land','Share of modelled sediment export','Mean modelled sediment export'][i],unit:i===2?'t/ha/year':'%',max:i===2?100:50});});}
 function knModel(){setContent(intro('Soil loss is not the same as sediment deposition.','The InVEST sediment-delivery assessment links potential hillslope erosion with the portion that can reach the stream network.')+'<div class="project-route" id="kn-model-route"></div><div id="kn-model-detail"></div><div id="kn-model-figure"></div>'+source('October erosion report, Sections 3–6; KN reference-run handover notes. The original raster figures depict the earlier model extent and are shown as report illustrations; interactive statistics use the final boundary.'));
  const stages=[['Soil loss','At the source','Potential long-term sheet and rill erosion','Rainfall erosivity, soil erodibility, terrain, cover and conservation factors combine to estimate potential soil detachment. This does not include all erosion processes.','erosion'],['Stream delivery','Along a pathway','The share that reaches streams','Landscape connectivity determines how much modelled hillslope soil loss reaches the stream network. It is smaller than gross soil loss because some material is retained upslope.','export'],['Deposition','Beyond this model','Reservoir siltation is a separate question','This reference model does not route sediment through channels or calculate trapping in reservoirs, tanks or canals. Sediment monitoring and routing are needed for that question.',null]];
  function draw(i){$('#kn-model-route').innerHTML=stages.map((r,j)=>`<button type="button" data-stage="${j}" aria-pressed="${i===j}">${r[0]}<small>${r[1]}</small></button>`).join('');$('#kn-model-detail').innerHTML=focus(stages[i][2],stages[i][3]);$('#kn-model-figure').innerHTML=stages[i][4]?figure(stages[i][4],i?'Report map · modelled sediment delivery to streams':'Report map · modelled gross soil erosion',570):takeaway('Use these results to identify places for closer review, not to claim an observed reduction in reservoir sedimentation.');$$('[data-stage]').forEach(b=>b.onclick=()=>draw(+b.dataset.stage));bindFigures();}draw(0);}
 function knWater(){setContent(intro('Follow water from the hills to its uses.','The hydrological assessment examines availability, demand and connections through both natural drainage and managed water systems.','Assessment approach')+'<div id="kn-water-questions"></div>'+photo(knPhotos.structure,'Irrigation control structure','Photograph used in the Knuckles project progress materials',380)+source(knRef+' Tasks 1.b–1.c and 2.'));
  decisions('#kn-water-questions',[['Rainfall, flow and storage','When is water available?','Bring together rainfall, streamflow, reservoir operation and catchment data. SWAT modelling is intended to describe seasonal water balance, river flow and sediment processes.'],['Water requirements','Who needs water, and when?','Assess irrigation, domestic and other demands alongside environmental-flow requirements. Compare seasonal requirements with availability.'],['Natural and managed connections','How does water move between systems?','Account for rivers, tanks and reservoirs as well as canals, transfers and diversions. Geographic proximity alone does not establish a hydrological connection.'],['Planning implications','Where do shortages or pressures emerge?','Use a consistent sub-watershed framework to identify seasonal constraints and support discussion of water-management priorities.']]);}
 function knClimate(){setContent(intro('Test future conditions, not a single forecast.','Climate scenarios are intended to drive hydrological simulations and reveal how water conditions may change.','Planned climate and hydrological assessment')+'<div id="kn-climate-tabs"></div><div id="kn-climate-detail"></div>'+list([['Hydrological questions','How might river flow, soil moisture, evapotranspiration and groundwater recharge change?'],['Risk questions','Where could flood and drought pressures increase, and which water systems or communities may be exposed?']])+method('Scenario design and result status','The Inception Report specifies MPI-ESM1-2-HR climate inputs dynamically downscaled with WRF to about 15 km, with a 1985–2014 baseline and SSP2-4.5 / SSP5-8.5 pathways. Future assessment windows are proposed for consultation. No final Knuckles-specific numerical climate-change results were established in the reviewed evidence, so this view explains the analysis rather than borrowing the ADB Uma Oya results.')+source('Revised Inception Report, Tasks 1.d, 2.d and 2.e.'));
  tabs('#kn-climate-tabs',['Historical baseline','SSP2-4.5','SSP5-8.5'],i=>{const rows=[['1985–2014 baseline','Establish a reference climate.','Check available observations and climate inputs, then assess model performance before comparing future conditions.'],['SSP2-4.5','Explore an intermediate forcing pathway.','Apply the scenario climate inputs to the hydrological model and compare the resulting seasonal and extreme water conditions with the baseline.'],['SSP5-8.5','Explore a higher forcing pathway.','Test how the hydrological system responds under stronger forcing. It is a conditional scenario, not a prediction that this pathway will occur.']];$('#kn-climate-detail').innerHTML=status('Assessment design',true)+focus(rows[i][1],rows[i][2],rows[i][0]);});}
 function knGroundwater(){setContent(intro('Look beneath the surface.','Groundwater and soil moisture help sustain water availability between rainfall events.','Planned baseline and scenario work')+photo(knPhotos.field,'Water-source field assessment in project progress materials','Field-assessment photograph from the Knuckles progress presentation',480)+'<div id="kn-groundwater"></div>'+source('Revised Inception Report, baseline groundwater and recharge assessment; Tasks 2.d–2.e.'));
  decisions('#kn-groundwater',[['Water sources','Compile the available groundwater evidence.','Use records of wells, boreholes and aquifer conditions, together with targeted field observations where data gaps matter.'],['Recharge potential','Combine terrain and hydrological information.','Geology, soils, slope, drainage, rainfall and modelled recharge help identify potential recharge zones and compare sub-watersheds.'],['Soil moisture','Assess water stored in the soil.','Use modelled soil-water conditions, supplemented where possible by satellite information, to examine seasonal water deficits and future changes.']]);}
 function knVulnerability(){setContent(intro('Risk depends on more than the hazard.','Climate hazards, exposure, sensitivity and adaptive capacity answer different questions.','Vulnerability assessment framework')+'<div id="kn-risk-tabs"></div><div id="kn-risk-detail"></div>'+takeaway('The current GN vulnerability work plan has not produced GN scores. Hazard and exposure assessments remain separate companion inputs, rather than an invented combined ranking.')+method('Methods and boundaries','The current work plan proposes GN resource-profile data for sensitivity and adaptive capacity, exploratory factor analysis where suitable, and tests of how erosion information should be integrated. Indicators, data quality and interpretation need to be settled before scores are used to prioritise action.')+source('GN Climate Vulnerability Assessment work plan and START_HERE; Inception Report, Tasks 1.d and 2.c.'));
  const rows=[['Hazard','What physical event or pressure could occur?','Examples include floods, droughts and erosion. Historical information and future model scenarios help characterise their location and severity.'],['Exposure','What lies in the affected area?','Locate people, water infrastructure and productive assets in relation to the relevant hazard footprint.'],['Sensitivity','How strongly could people or systems be affected?','Use suitable local indicators to examine dependence, susceptibility and existing constraints.'],['Adaptive capacity','What helps people prepare, respond and recover?','Consider the available services, resources, capabilities and institutional support.']];tabs('#kn-risk-tabs',rows.map(r=>r[0]),i=>{$('#kn-risk-detail').innerHTML=status('Framework · scores not yet calculated',true)+focus(rows[i][1],rows[i][2],rows[i][0]);});}
 function knInfrastructure(){setContent(intro('Assess the system before selecting repairs.','The proposed infrastructure assessment combines physical condition, operation, benefit and climate risk.','Proposed screening approach')+'<div id="kn-infrastructure-chart"></div>'+takeaway('Structural condition receives the largest proposed weight. Climate risk is also explicit, so prioritisation goes beyond visible damage alone.')+list([['Build a georeferenced inventory','Compile locations and available records for relevant tanks, anicuts, ponds, canals and drainage systems.'],['Inspect priority systems','Combine targeted site visits with information from farmers, officers and managing institutions. This is not a commitment to inspect every canal.'],['Support the design teams','Share the assessment and rehabilitation needs. Detailed engineering design and works remain with the responsible consultants and agencies.']])+source('Revised Inception Report, infrastructure assessment criteria and proposed weights. These percentages are methodological weights, not measured infrastructure condition or a final investment ranking.'));
  barChart('#kn-infrastructure-chart',[['Structural integrity',35],['Operation & hydrology',15],['Social & farm benefit',10],['Maintenance urgency',10],['Climate risk',20],['Ecological factors',10]].map(([label,value],i)=>({label,value,color:colors[i]})),{unit:'% proposed weight',title:'Proposed infrastructure-screening weights',max:40});}
 function knSupport(){setContent(intro('Evidence that other teams can use.','IWMI’s role is to supply hydrological analysis and strategic guidance within a coordinated project.','Technical support · no direct field implementation')+'<div id="kn-support"></div>'+source('Revised Inception Report, Tasks 3.a–3.c and 4.a–4.b.'));
  decisions('#kn-support',[['Shared spatial framework','Use compatible units and data.','Provide sub-watershed boundaries, connectivity information and metadata so different consultants can align their analyses.'],['Design inputs','Make the hydrology visible in decisions.','Share flow regimes, sediment pathways, erosion priorities and climate considerations to inform streamside protection, drainage and infrastructure rehabilitation.'],['Watershed recommendations','Compare suitable management responses.','Bring model scenarios, land-use diagnostics and field information into discussion of conservation and watershed-management priorities.'],['Institutional interface','Work through agreed responsibilities.','MCB facilitates coordination and information exchange. Universities, engineering consultants and other responsible teams undertake complementary studies and detailed design.']]);}
 function knPriorities(){setContent(intro('From a model hotspot to a practical decision.','A spatial priority is a starting point for closer assessment, not a ready-to-build intervention.')+flow([['Identify candidate source areas','Consider both high mean erosion or delivery rates and large local contributions. Use the final-boundary map consistently.'],['Check the place and assumptions','Review land cover, actual conditions, model coefficients, data coverage and community knowledge before selecting a response.'],['Assess the response in context','Consider hydrological effects, feasibility, livelihood needs, climate exposure and maintenance responsibilities with the relevant teams.'],['Share recommendations and follow up','Provide maps, evidence and guidance to the design and implementation teams; use monitoring to improve the evidence over time.']])+jumpButtons([['Explore erosion evidence',1,0],['Technical responsibilities',3,1]])+method('Current limitations','The reference erosion model is uncalibrated. It omits channel/bank processes and reservoir trapping, and depends on cover/practice assumptions. Fine GN rankings are especially sensitive to small clipped areas and boundary overlaps; this exhibit therefore presents the consistent 35-unit framework.')+source('October erosion assessment and technical handover limitations; Inception Report, Tasks 3–4.'));bindJumps();}
 function knCapacity(){setContent(intro('Build the capability to use the evidence.','Capacity development follows a learning-by-doing approach, using project data and practical watershed questions.','Planned capacity-development pathway')+'<div id="kn-capacity-path"></div>'+source('Revised Inception Report, Task 5.a–5.d. Training completion counts are not established in the reviewed evidence.'));
  decisions('#kn-capacity-path',[['Assess needs','Start with the agencies’ actual capacity.','Review technical skills, data systems, available tools and coordination arrangements. Identify the gaps that matter most for the work.'],['Learn with project data','Practice the complete analytical workflow.','Prepare data, set up models, check performance, run scenarios and interpret outputs through supported practical work.'],['Mentor a technical team','Build confidence through joint work.','The Inception Report proposes a small multi-agency technical team of about 3–5 officers, with ongoing mentoring and a training-of-trainers approach.'],['Leave usable tools','Make knowledge repeatable.','Provide technical guidelines, manuals, standard workflows and training materials aligned with institutional needs.']]);}
 function knParticipants(){setContent(intro('From shared learning to institutional ownership.','The intended users include technical staff and decision-makers in the agencies responsible for water management.')+photo(knPhotos.training,'IWMI climate-information workshop in Matara','Illustrative IWMI training photograph · Matara Climate Information Systems workshop, February 2025. This is not a Knuckles training event.',390)+list([['Technical agencies','MASL, Irrigation Department, MCB and other nominated institutions can use the modelling, GIS and climate-analysis workflows.'],['Local stakeholders','Community knowledge and local priorities inform the assessment. MCB leads field-level engagement and outreach arrangements.'],['Internal trainers','A training-of-trainers approach is intended to allow participating officers to support colleagues and sustain use of the tools.']])+takeaway('The objective is the ability to use the analysis independently, rather than only attendance at a workshop.')+source('Revised Inception Report, Task 5. Photograph provenance: Matara CIS_Feb_2025.pptx, slide 20; used as an explicitly labelled example.'));}
 function knMonitoring(){setContent(intro('Track progress, use and learning.','The monitoring framework is intended to connect technical outputs with institutional uptake and continued use.','Planned monitoring and evaluation')+'<div id="kn-monitoring"></div>'+takeaway('Indicators describe what should be tracked. This display does not assign unverified progress percentages or completed-beneficiary totals.')+source('Revised Inception Report, Task 6 and Table 4. Indicators are presented for the IWMI-led components; broader programme delivery is the responsibility of the relevant partners.'));
  decisions('#kn-monitoring',[['Technical quality','Are the analytical tools fit for purpose?','Track sub-watersheds modelled, updated datasets and model performance against appropriate observations.'],['Planning evidence','Are priority areas documented?','Track the erosion-prone sites and extents identified, and the maps and recommendations supplied to planning teams.'],['Capacity and uptake','Can institutions use the tools?','Track officers trained, institutional application and continued functionality of monitoring systems. Attendance alone does not establish independent capability.'],['Feedback and adaptation','What changes after review?','Use responsibilities, reporting mechanisms and learning discussions to refine the work as new evidence and experience become available.']]);}
 function knStatus(){setContent(intro('What can be explored now—and what follows.','The exhibit separates the evidence present in the project records from assessments described in the work programme.','Evidence reviewed · 4 November 2026')+list([['Available · spatial framework','Adopted 35-unit sub-watershed framework, upstream/downstream grouping, supporting maps and spatial data.'],['Available · model-based erosion evidence','Final-boundary reference results and revised draft reporting. These support relative comparison; they are not a calibrated sediment budget or a claim of formal project acceptance.'],['Planned / developing · hydrology and climate','Baseline water balance, future climate impacts, water demand, groundwater and infrastructure-vulnerability assessment are described in the work programme. Final numerical results are not presented here without verified outputs.'],['Not yet scored · GN vulnerability','The current work plan explicitly states that the statistical template has not been executed and GN vulnerability scores have not been calculated.'],['Planned · skills, recommendations and M&E','Guidelines, capacity strengthening, technical support and monitoring arrangements are part of the assignment. Delivery counts and outcomes require their own records.']])+source('Delineation report; October erosion model handover and revised draft; Inception Report; current GN vulnerability work plan. This is an evidence inventory for the exhibit, not an official project-progress certification.'));}
 function knSummary(){setContent(intro('Better evidence for resilient water decisions.','The study connects the physical landscape with the capabilities and decisions needed to manage it.')+metrics([['35','common assessment units'],['6','linked workstreams'],['4','river basins']])+list([['A common view of the landscape','Use consistent boundaries to link upstream and downstream questions.'],['Targeted investigation','Relative erosion contributions help identify places requiring closer review and locally informed planning.'],['Decisions supported by science','Hydrological and climate analysis informs the responsible teams’ design and management choices.'],['Lasting capability','Practical tools, institutional learning and monitoring support continued use beyond individual reports.']])+jumpButtons([['Explore the map',1,0],['Water & climate',2,0],['Skills & learning',4,0]])+source('Synthesis of the Knuckles project scope and reviewed technical evidence.'));bindJumps();}
 function knSources(){return intro('Evidence behind Knuckles.','Results and proposed work are distinguished throughout the presentation.')+list([['Scope · Inception Report, 6 April 2026','The complete project work programme: hydrology, climate risk, connectivity, infrastructure, technical support, capacity development and monitoring. The exhibit follows the responsibility boundaries in Tasks 3–5.'],['Delineation · September 2026','Watershed and Sub-Watershed Delineation Report. The adopted framework contains 35 units; 30 m SRTM and drainage/outlet checks support catchment-scale planning.'],['Erosion · final-boundary reference analysis','KN_Analysis_Handover_20261009 / 11_Final_boundary_results: KN_Analysis.gpkg, Subwatershed_results.csv, Landuse_contributions.csv, Upstream_downstream_results.csv and River_basin_results.csv. Fresh final-boundary results take precedence over earlier reaggregations.'],['Interpretation · October revised draft','GCF_Knuckles_Soil_Erosion_Vulnerability_Assessment_Report_Oct2026_Revised_Clean_v2_maps.docx. Used for narrative and original map figures, cross-checked against the underlying reference-run data.'],['GN vulnerability · current work plan','Climate_Vulnerability_Assessment / START_HERE and the detailed GN work plan: no calculated GN vulnerability scores or completed statistical run are claimed.']])+method('Areas, valid cells and precision','Geographical area from geometry is 7,321.514 km²; the delivered area attribute totals 7,322.368 km². Interactive area and area-share calculations use geometry. Gross erosion excludes stream cells and missing input cells; sediment export has additional missing non-stream cells. Means use their respective valid areas. Missing data are not treated as zero.')+method('What the erosion model does and does not represent','The reference run estimates long-term sheet-and-rill soil loss and hillslope delivery to streams. Totals are about 5.21 million t/year gross erosion and 0.918 million t/year export. These uncalibrated values are planning references, not measured sediment loads, outlet loads or reservoir deposition. The exhibit emphasises relative contributions. Landslide-surface estimates describe exposed soil after a slide, not the volume mobilised in the slide itself.')+method('Sensitive inputs and finer-scale results','Rainfall inputs have mixed periods and duplicate-station issues. Cover/practice assumptions need review; open forest was assigned dense-forest values in the reference run. GN summaries can be distorted by very small clipped areas and overlapping polygons. No fine-scale GN ranking or unsupported calibration result is presented.')+method('Maps and photographs','Interactive polygons come from the final-boundary GeoPackage and are generalised only for display. Numeric results are preserved. Raster erosion figures in the October report were prepared for an earlier run and are labelled as report illustrations. The Knuckles hero and field/infrastructure photographs come from project materials. The Matara workshop is explicitly labelled as an example from another IWMI project.')+method('Why some screens explain methods instead of showing results','The Inception Report describes intended outputs, not completed findings. Knuckles climate projections, GN vulnerability scores, training totals and intervention impacts are not fabricated or copied from the separate ADB Uma Oya assessment. Available reference-model results and remaining assessments are clearly labelled.')+source('Original sources, extracted tables, image provenance, preparation scripts and numerical checks are retained in research_projects.');}
 const knChapters=[
  {title:'The landscape & the assignment',desc:'Upstream–downstream connections and IWMI’s role.',topics:['Purpose','Study framework','Six workstreams'],fn:[knPurpose,knBoundary,knFramework]},
  {title:'Explore erosion evidence',desc:'Select places and compare modelled contributions.',topics:['Interactive map','Contributions','Land cover','Read the model'],fn:[knMap,knContribution,knLanduse,knModel]},
  {title:'Water & a changing climate',desc:'Availability, demand, groundwater and vulnerability.',topics:['Water systems','Climate scenarios','Groundwater','Vulnerability'],fn:[knWater,knClimate,knGroundwater,knVulnerability]},
  {title:'Evidence into planning',desc:'Infrastructure needs and technical support to partners.',topics:['Infrastructure','Technical support','Priority decisions'],fn:[knInfrastructure,knSupport,knPriorities]},
  {title:'Skills, institutions & learning',desc:'Practical capability and a framework for monitoring.',topics:['Capacity pathway','Institutional ownership','Monitoring'],fn:[knCapacity,knParticipants,knMonitoring]},
  {title:'Delivery & the next decisions',desc:'Available evidence, planned assessments and key messages.',topics:['Evidence status','Key messages'],fn:[knStatus,knSummary]}
 ];
 window.registerStudyProject('knuckles',{data:{watersheds:KN},photos:knPhotos,chapters:knChapters,title:'Knuckles<br>Mountain Range',plainTitle:'Knuckles Mountain Range · Water Science for Climate Resilience',subtitle:'Water science for climate resilience.',kicker:'IWMI · GCF Knuckles hydrological study',heroAlt:'The Knuckles mountain landscape',overviewTitle:'Connect the hills with the decisions.',overviewText:'Explore the landscape, the available erosion evidence and the wider programme of hydrology, climate analysis and institutional learning.',metrics:[['35','sub-watersheds'],['12 / 23','upstream / downstream'],['4','river basins']],sources:knSources});
 window.addEventListener('message',e=>{if(e.source!==parent)return;const key=e.data==='iwmi-open-mahaweli'?'mahaweli':e.data==='iwmi-open-knuckles'?'knuckles':null;if(key){const toggle=document.getElementById('menu-toggle');if(toggle.getAttribute('aria-expanded')!=='true')toggle.click();document.querySelector('[data-project="'+key+'"]').click();}});
})();
